sketch.css:
.cc{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:10px;padding:12px 14px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.cc *{box-sizing:border-box}
.totals{display:flex;gap:22px}
.tot .tl{color:var(--muted);font-size:11.5px;font-weight:500}
.tot .tv{font-size:20px;font-weight:700;letter-spacing:-.01em;line-height:1.2}
.tot .tv small{font-size:12px;font-weight:500;color:var(--muted);margin-left:3px}
.tot.good .tv{color:var(--green)}
.table{flex:1;display:flex;flex-direction:column;min-height:0;border-top:1px solid var(--border)}
.colhead,.row{display:grid;grid-template-columns:1.4fr 96px 1fr 72px 80px 52px;gap:10px;align-items:center}
.colhead{font-size:11px;font-weight:600;color:var(--muted);padding:6px 8px 4px;text-transform:uppercase;letter-spacing:.03em}
.r{text-align:right}
.rows{flex:1;overflow:auto}
.row{padding:6px 8px;border-radius:6px;cursor:pointer;border-bottom:1px solid var(--border)}
.row:hover{background:var(--hover)}
.row.selected{background:var(--hover);box-shadow:inset 3px 0 0 var(--accent)}
.name{display:flex;align-items:center;gap:7px;min-width:0}
.name b{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.prog{font-size:10px;font-weight:700;padding:0 6px;border-radius:8px;color:var(--c);background:color-mix(in srgb,var(--c) 14%,transparent);flex:none}
.price{text-align:right;line-height:1.2}
.price b{font-weight:700;font-variant-numeric:tabular-nums}
.price small{display:block;font-size:11px;font-weight:600}
.up{color:var(--green)}
.down{color:var(--red)}
.flat{color:var(--muted)}
.spark{height:24px}
.spark svg{display:block;width:100%;height:100%}
.held,.value,.uplift{text-align:right;font-variant-numeric:tabular-nums;font-size:12px}
.held{color:var(--muted)}
.value{font-weight:600}
.uplift{font-weight:700;color:var(--green)}
.empty{color:var(--muted);text-align:center;padding:30px 0}

