function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const cls = v => v > 0 ? 'up' : v < 0 ? 'down' : 'flat';
  const PROG = { RFS: 'var(--violet)', LCFS: 'var(--sky)', CFP: 'var(--green)', CFS: 'var(--amber)' };
  const money = v => v >= 1e6 ? '$' + (v / 1e6).toFixed(2) + 'M' : v >= 1e3 ? '$' + Math.round(v / 1e3) + 'k' : '$' + Math.round(v);
  const qty = v => v >= 1e6 ? (v / 1e6).toFixed(2) + 'M' : v >= 1e3 ? Math.round(v / 1e3) + 'k' : String(Math.round(v));
  // a price in cents shows as 104.5¢, in dollars as $72.50
  const price = c => c.unit === '¢' ? (+c.price || 0).toFixed(2) + '¢' : '$' + (+c.price || 0).toFixed(2);
  const credits = props.credits || [];

  // totals: holdings at market (cents converted to dollars) and the uplift a gallon earns in the selected market
  let value = 0;
  credits.forEach(c => value += (+c.held || 0) * (+c.price || 0) / (c.unit === '¢' ? 100 : 1));
  const rin = credits.find(c => c.id === 'd6');
  const sel = credits.find(c => c.id === props.selected);
  const uplift = (rin ? +rin.perGallon || 0 : 0) + (sel && sel !== rin ? +sel.perGallon || 0 : 0);
  root.querySelector('.totals').innerHTML =
    '<div class="tot"><div class="tl">Credits held, at market</div><div class="tv">' + money(value) + '</div></div>' +
    '<div class="tot good"><div class="tl">Uplift per gallon' + (sel && sel !== rin ? ' (D6 + ' + esc(sel.name) + ')' : '') + '</div><div class="tv">' + uplift.toFixed(1) + '<small>¢/gal</small></div></div>' +
    (props.rvo ? '<div class="tot"><div class="tl">RVO coverage</div><div class="tv">' + Math.round((rin ? +rin.held || 0 : 0) / props.rvo * 100) + '<small>%</small></div></div>' : '');

  const box = root.querySelector('.rows');
  root.querySelector('.colhead').style.display = credits.length ? '' : 'none';
  if (!credits.length) { box.innerHTML = '<div class="empty">No credits</div>'; return; }
  box.innerHTML = credits.map(c => {
    const ch = +c.change || 0, hist = (c.history || []).map(Number).filter(v => !isNaN(v));
    let spark = '';
    if (hist.length > 1) {
      const lo = Math.min.apply(null, hist), hi = Math.max.apply(null, hist), r = hi - lo || 1;
      const pts = hist.map((v, i) => (i / (hist.length - 1) * 100).toFixed(1) + ',' + (22 - (v - lo) / r * 20).toFixed(1)).join(' ');
      spark = '<svg viewBox="0 0 100 24" preserveAspectRatio="none"><polyline points="' + pts + '" fill="none" stroke="' + (hist[hist.length - 1] >= hist[0] ? 'var(--green)' : 'var(--red)') + '" stroke-width="1.6" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></svg>';
    }
    const v = (+c.held || 0) * (+c.price || 0) / (c.unit === '¢' ? 100 : 1);
    return '<div class="row' + (c.id === props.selected ? ' selected' : '') + '" data-id="' + esc(c.id) + '" style="--c:' + (PROG[c.program] || 'var(--accent)') + '">' +
      '<div class="name"><span class="prog">' + esc(c.program) + '</span><b>' + esc(c.name) + '</b></div>' +
      '<div class="price"><b>' + price(c) + '</b><small class="' + cls(ch) + '">' + (ch > 0 ? '▲ ' : ch < 0 ? '▼ ' : '■ ') + Math.abs(ch).toFixed(2) + '</small></div>' +
      '<div class="spark">' + spark + '</div>' +
      '<div class="held">' + qty(+c.held || 0) + '</div>' +
      '<div class="value">' + money(v) + '</div>' +
      '<div class="uplift">' + (+c.perGallon || 0).toFixed(1) + '</div></div>';
  }).join('');
  box.querySelectorAll('.row').forEach(el => el.onclick = () => fire('creditSelected', { id: el.dataset.id, selected: el.dataset.id }));
}
